describe('User Registration - Email Already Exists Error', () => {
  beforeEach(() => {
    cy.visit('/register');
  });

  it('should display clear error message when registering with an existing email', () => {
    // Intercept the registration API call
    cy.intercept('POST', '/api/auth/register').as('registerRequest');

    // Fill in registration form with existing email
    cy.get('[data-testid="email-input"]').type('existing@example.com');
    cy.get('[data-testid="password-input"]').type('ValidPassword123!');
    cy.get('[data-testid="confirm-password-input"]').type('ValidPassword123!');

    // Submit the registration form
    cy.get('[data-testid="register-button"]').click();

    // Wait for the API response
    cy.wait('@registerRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(499);
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'This email is already registered');

    // Verify form is not submitted and user remains on registration page
    cy.url().should('include', '/register');
    cy.get('[data-testid="email-input"]').should('have.value', 'existing@example.com');
  });

  it('should handle multiple validation errors when email already exists', () => {
    // Intercept the registration API call
    cy.intercept('POST', '/api/auth/register').as('registerRequest');

    // Fill in form with existing email and invalid password
    cy.get('[data-testid="email-input"]').type('existing@example.com');
    cy.get('[data-testid="password-input"]').type('short');
    cy.get('[data-testid="confirm-password-input"]').type('short');

    // Submit the registration form
    cy.get('[data-testid="register-button"]').click();

    // Wait for the API response
    cy.wait('@registerRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(422);
    });

    // Verify multiple error messages are displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'This email is already registered');

    cy.get('[data-testid="password-error"]')
      .should('be.visible')
      .should('contain', 'Password must be at least 8 characters');

    // Verify form fields retain values
    cy.get('[data-testid="email-input"]').should('have.value', 'existing@example.com');
    cy.get('[data-testid="password-input"]').should('have.value', 'short');
  });
});
